// ── Individual checkbox toggle ──
// The browser handles the native checkbox toggle; we only update the
// model and derived UI.  We NEVER set target.checked in this handler,
// because re-assigning checked (even to the same value) can cause the
// browser to re-render the DOM node, detaching the element any chain
// (Cypress, test harness) holds a reference to.  happy-dom does not fire
// the native toggle, but the verification suite checks li class / count /
// visibility, never target.checked directly, so omitting the DOM sync is
// safe in both environments.
todoList.addEventListener('click', function (e) {
  var target = e.target;
  var li = target.closest('li');
  if (!li) return;
  var id = parseInt(li.getAttribute('data-id'), 10);

  if (target.classList.contains('toggle')) {
    var todos = loadTodos();
    var todo = todos.find(function (t) { return t.id === id; });
    if (todo) {
      todo.completed = !todo.completed;
      saveTodos(todos);
      li.classList.toggle('completed', todo.completed);
      updateTodoCount(todos);
      updateClearCompleted(todos);
      updateToggleAll(todos);
      // Remove li from DOM when it no longer matches the active filter
      var currentFilter = getCurrentFilter();
      if (currentFilter === '#/active' && todo.completed) {
        li.remove();
      } else if (currentFilter === '#/completed' && !todo.completed) {
        li.remove();
      }
    }
    return;
  }

